def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        freq = {}
        freq_map = {}
        min_freq = 0
        max_size = maxsize

        def make_key(*args, **kwargs):
            if typed:
                return (func, args, tuple(sorted(kwargs.items())))
            else:
                if not func.__code__.co_varnames:
                    return args + (tuple(sorted(kwargs.items())),)
                import inspect
                sig = inspect.signature(func)
                bound = sig.bind(*args, **kwargs)
                bound.apply_defaults()
                return tuple(bound.arguments.values())

        def _incr_freq(key):
            nonlocal min_freq
            freq[key] = freq.get(key, 0) + 1
            if freq[key] == 1:
                min_freq = 1
            freq_map.setdefault(freq[key], []).append(key)
            if key in freq_map.get(min_freq - 1, []):
                freq_map[min_freq - 1].remove(key)
                if not freq_map[min_freq - 1]:
                    del freq_map[min_freq - 1]

        def _evict_lfu():
            nonlocal min_freq
            lfu_keys = freq_map.get(min_freq, [])
            if lfu_keys:
                evict_key = lfu_keys.pop(0)
                if not lfu_keys:
                    del freq_map[min_freq]
                if freq_map[min_freq] == []:
                    del freq_map[min_freq]
                del cache[evict_key]
                del freq[evict_key]
                # find next min_freq
                while min_freq in freq_map and freq_map[min_freq]:
                    min_freq += 1
                if not freq_map:
                    min_freq = 0
            else:
                # find next min_freq
                while min_freq in freq_map and not freq_map[min_freq]:
                    min_freq += 1

        def wrapper(*args, **kwargs):
            nonlocal min_freq
            k = make_key(*args, **kwargs)
            if k in cache:
                _incr_freq(k)
                return cache[k]
            v = func(*args, **kwargs)
            # When inserting new items, we may need to evict
            if len(cache) < max_size:
                cache[k] = v
                _incr_freq(k)
            else:
                # evict LRU
                if k in cache:
                    _incr_freq(k)
                    cache[k] = v
                else:
                    if max_size > 0:
                        _evict_lfu()
                        cache[k] = v
                        _incr_freq(k)
                    else:
                        # maxsize <= 0, just don't cache
                        pass
            return v

        wrapper.cache = cache
        return wrapper
    return decorator
