            # Get or create the frequency count
            if key not in cache:
                # Check if cache is full
                if len(cache) >= maxsize:
                    # Find the key with the least frequency
                    min_freq = min(freq.values()) if freq else 0
                    # Remove one key with the minimum frequency
                    keys_to_remove = [k for k, f in freq.items() if f == min_freq]
                    for k in keys_to_remove:
                        if len(cache) >= maxsize:
                            del cache[k]
                            del freq[k]
                            if typed and k in cache_types:
                                del cache_types[k]
                            break
                cache[key] = func(*args, **kwargs)
                freq[key] = 0
            else:
                # Increment frequency
                freq[key] += 1

            # Track types if needed
            if typed:
                cache_types[key] = (args, kwargs)

            return cache[key]

        # Add a clear function
        def clear():
            cache.clear()
            freq.clear()
            if typed:
                cache_types.clear()

        wrapper.cache = cache
        wrapper.clear = clear
        wrapper.func = func
        wrapper._wrapped = True

        # Use functools.wraps to preserve function metadata
        try:
            from functools import wraps
            return wraps(func)(wrapper)
        except ImportError:
            # Python 2 compatible fallback
            wrapper.__name__ = func.__name__
            wrapper.__doc__ = func.__doc__
            wrapper.__module__ = func.__module__
            wrapper.__dict__.update(func.__dict__)
            return wrapper
    return decorator
