    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        try:
            import traceback
            import sys

            # Get the traceback
            tb = e.__traceback__
            if tb is None:
                return str(e)

            # Extract frames from the traceback
            frames = traceback.extract_tb(tb)

            # Limit the number of frames
            if len(frames) > max_level:
                frames = frames[-max_level:]

            # Calculate the common prefix for the file paths
            min_lines = min(len(frame) for frame in frames)
            prefix_length = 0
            for i in range(min_lines):
                for j in range(1, len(frames)):
                    if frames[0][i] != frames[j][i]:
                        break
                else:
                    prefix_length = i + 1
                if j != len(frames) - 1:
                    break

            # Get the common prefix
            common_prefix = frames[0][i] if i < len(frames[0]) else ''

            # Build the formatted string
            lines = []
            lines.append('Traceback (most recent call last):')
            for frame in frames:
                filename, lineno, name, line = frame
                if filename.startswith(common_prefix):
                    filename = filename.replace(common_prefix, '')
                lines.append('  File "%s", line %s, in %s' % (filename, lineno, name))
                if line is not None:
                    lines.append('    %s' % line)

            exception_msg = '%s: %s' % (e.__class__.__name__, e)
            lines.append(exception_msg)

            return '\n'.join(lines)
        except Exception as ex:
            return 'Error formatting exception: %s' % str(ex)
