def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        classes = [classes]

    # Filter out None and non-class objects
    valid_classes = [cls for cls in classes if isinstance(cls, type)]

    if len(valid_classes) <= 1:
        return valid_classes if valid_classes else []

    # Remove duplicates while preserving order
    seen = set()
    unique_classes = []
    for cls in valid_classes:
        if cls not in seen:
            seen.add(cls)
            unique_classes.append(cls)

    if len(unique_classes) <= 1:
        return unique_classes if unique_classes else []

    # Remove any class that is a subclass of another class in the list
    minimal = []
    for i, cls in enumerate(unique_classes):
        is_redundant = False
        for j, other in enumerate(unique_classes):
            if i != j and issubclass(cls, other):
                is_redundant = True
                break
        if not is_redundant:
            minimal.append(cls)

    return minimal
