def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Handle empty input
    if not classes:
        return []

    # Remove exact duplicates while preserving order
    unique_classes = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"All items must be classes, got {type(cls)}")
        if cls not in seen:
            seen.add(cls)
            unique_classes.append(cls)

    # Remove classes that are subclasses of other classes in the list
    # A class A is redundant if there's another class B in the list such that B is a subclass of A
    # We want to keep the most specific classes (subclasses) and remove their superclasses

    # Convert to list for indexing
    result = []
    for i, cls in enumerate(unique_classes):
        # Check if any other class in unique_classes is a subclass of cls
        is_super = False
        for j, other_class in enumerate(unique_classes):
            if i == j:
                continue
            # If other_class is a subclass of cls (and not the same), then cls is a superclass of a more specific class
            # In that case, cls can be removed
            if issubclass(other_class, cls):
                is_super = True
                break
        if not is_super:
            result.append(cls)

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for cls in classes:
        is_minimal = True
        for other in result:
            if issubclass(cls, other):
                is_minimal = False
                break
        if is_minimal:
            new_result = []
            for existing in result:
                if issubclass(existing, cls):
                    continue
                new_result.append(existing)
            new_result.append(cls)
            result = new_result
    return result

