def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect names from inherited interfaces
    inherited_names = set()
    for base in self.__bases__:
        try:
            # Check if it's an interface object (has getAttributeNames method)
            if hasattr(base, 'getAttributeNames'):
                inherited_names.update(base.getAttributeNames())
        except TypeError:
            # Not an interface object, skip
            pass

    # Collect own attribute names
    own_names = set()
    for name, value in self._attributes.items():
        # Only include attribute names that are defined in this interface
        if hasattr(value, '_is_attribute'):
            own_names.add(name)

    if all:
        return sorted(inherited_names.union(own_names))
    else:
        return sorted(own_names)

