def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If the sequence is a Broken object, just return it as is
    if getattr(sequence, '__broken__', False):
        output.append(sequence)
        return output

    cls = sequence.__class__

    # Check if it's an InterfaceClass (from zope.interface)
    try:
        from zope.interface import InterfaceClass, implements, Implements
    except ImportError:
        InterfaceClass = None
        Implements = None
        implements = None

    if InterfaceClass is not None:
        if isinstance(sequence, InterfaceClass):
            output.append(sequence)
            return output

    # Check if it's an Implements specification
    if Implements is not None:
        if isinstance(sequence, Implements):
            output.append(sequence)
            return output

    # If it's a tuple or list, expand it
    if isinstance(sequence, (list, tuple)):
        for item in sequence:
            _normalizeargs(item, output)
        return output

    # If it's a class that implements, check if it has the __implemented__ attribute
    # or is a declaration
    import zope.interface.declarations as declarations

    if isinstance(sequence, declarations.Declaration):
        output.append(sequence)
        return output

    # Default: expand it
    try:
        for item in sequence:
            _normalizeargs(item, output)
    except TypeError:
        output.append(sequence)

    return output
