def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Check for infinite values
    if np.any(np.isinf(edges)):
        return np.cumprod(bins)

    # Check for invalid bin ranges
    for i in range(len(edges) - 1):
        if edges[i + 1] <= edges[i]:
            raise ValueError('Edges must be monotonically increasing.')

    # Compute the integral (sum of bin values multiplied by the width of each bin)
    integral_value = 0.0
    for i in range(len(edges) - 1):
        width = edges[i + 1] - edges[i]
        integral_value += bins[i] * width

    return integral_value

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
  # Input validation
  if bins is None or edges is None:
    raise ValueError("bins and edges must be provided")

  try:
    bins = np.asarray(bins)
    edges = np.asarray(edges)
  except Exception:
    raise ValueError("bins and edges must be convertible to numpy arrays")

  # Check dimensions
  if bins.ndim != 1 or edges.ndim != 1:
    raise ValueError("bins and edges must be 1-dimensional arrays")

  # Check that edges is one element longer than bins (edges define bin boundaries)
  # In histogram context, len(edges) should be len(bins) + 1
  if len(edges) != len(bins) + 1:
    raise ValueError("edges must have length len(bins) + 1")

  try:
    total = np.sum(bins * np.diff(edges))
    return total
  except Exception as e:
    raise ValueError("Error computing integral: {}".format(str(e)))

