def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        if self.ndim != len(coord):
            raise ValueError("coord must have the same number of dimensions as the histogram.")

        # Check if coordinates are within bins
        for i, c in enumerate(coord):
            if not (self.edges[i][0] <= c < self.edges[i][-1]):
                return  # Ignore if outside

        # Find the bin indices
        bins = [np.searchsorted(self.edges[i], c, side='right') - 1 for i, c in enumerate(coord)]
        self._filled[tuple(bins)] += weight
    except Exception as e:
        pass

