        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("fixity must be a dictionary")

        # Check for the required structure
        for key in fixity:
            if not isinstance(key, str):
                raise ValueError("fixity keys must be strings")

            checksum = fixity[key]
            if not isinstance(checksum, str):
                raise ValueError("fixity values must be strings (checksums)")

        # Ensure that all files in fixity are listed in manifest_files
        for file_path in fixity:
            if file_path not in manifest_files:
                raise ValueError("File '%s' in fixity block is not in manifest" % file_path)

