def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET
    import logging
    import traceback

    logger = logging.getLogger(__name__)
    packages = {}

    try:
        if not os.path.isdir(folder):
            logger.warning(f"Folder '{folder}' does not exist or is not a directory.")
            return {}

        for root, dirs, files in os.walk(folder):
            for file in files:
                if file.endswith('.xml'):
                    file_path = os.path.join(root, file)
                    # Use the filename without extension as the key (basename)
                    base_name = os.path.splitext(file)[0]
                    try:
                        # Parse the XML file
                        tree = ET.parse(file_path)
                        data = tree.getroot()

                        # Group by base_name
                        if base_name not in packages:
                            packages[base_name] = []

                        packages[base_name].append({
                            'filename': file,
                            'path': file_path,
                            'data': data
                        })
                    except ET.ParseError as e:
                        logger.exception(f"Failed to parse XML file: {file_path}. Error: {str(e)}")
                        traceback.print_exc()
                    except Exception as e:
                        logger.exception(f"Unexpected error processing XML file: {file_path}. Error: {str(e)}")
                        traceback.print_exc()
    except Exception as e:
        logger.exception(f"Unexpected error exploring folder '{folder}'. Error: {str(e)}")
        traceback.print_exc()

    return packages

