            for file in files:
                if file.endswith('.xml'):
                    filepath = os.path.join(root, file)
                    try:
                        tree = ET.parse(filepath)
                        root_element = tree.getroot()

                        filename_without_ext = os.path.splitext(file)[0]

                        xml_data = {
                            'folder': root,
                            'file': file,
                            'full_path': filepath,
                            'root_tag': root_element.tag,
                            'data': {}
                        }

                        for child in root_element:
                            xml_data['data'][child.tag] = child.text

                        if filename_without_ext not in data:
                            data[filename_without_ext] = []

                        data[filename_without_ext].append(xml_data)

                    except ET.ParseError:
                        continue
                    except Exception:
                        continue

    except Exception:
        pass

    return data

