def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not zip_path or not os.path.exists(zip_path):
        return {}

    try:
        myzip = zipfile.ZipFile(zip_path, mode='r')
    except (IOError, zipfile.BadZipFile):
        return {}

    datadict = {}
    for fname in myzip.namelist():
        try:
            if fname.endswith(".xml"):
                base = os.path.splitext(os.path.basename(fname))[0]
                if base not in datadict:
                    datadict[base] = {}
                datadict[base][fname] = myzip.read(fname)
        except Exception:
            continue
    return datadict

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"Zip file does not exist: {zip_path}")

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for file_name in zf.namelist():
                if file_name.endswith('/'):
                    continue  # Skip directories
                if not file_name.endswith('.xml'):
                    continue  # Only process XML files

                # Extract basename without extension for grouping
                base_name = os.path.splitext(os.path.basename(file_name))[0]

                # Read the file content
                with zf.open(file_name) as f:
                    content = f.read()

                # Add to the packages dict
                if base_name not in packages:
                    packages[base_name] = {}
                packages[base_name][file_name] = content

    except zipfile.BadZipFile:
        raise RuntimeError(f"Invalid zip file: {zip_path}")
    except Exception as e:
        raise RuntimeError(f"Error exploring zip file: {e}")

    return packages

