        # Check negative absorption: A & (~A | B) = A & B  or A | (~A & B) = A | B
        if isinstance(expr1, And) and isinstance(expr2, Or):
            for a in expr1.args:
                for b in expr2.args:
                    if a == Not(b):
                        # A & (Not(A) | B) => A & B
                        return And(a, b)
        if isinstance(expr1, Or) and isinstance(expr2, And):
            for a in expr1.args:
                for b in expr2.args:
                    if a == Not(b):
                        # A | (Not(A) & B) => A | B
                        return Or(a, b)

        return None

    # Generate all unique pairs
    new_args = list(args)
    changed = True
    while changed:
        changed = False
        new_args_next = list(new_args)
        for i in range(len(new_args)):
            for j in range(i + 1, len(new_args)):
                x, y = new_args[i], new_args[j]
                result = _absorb(x, y)
                if result is not None:
                    new_args_next = [a for idx, a in enumerate(new_args) if idx not in (i, j)]
                    new_args_next.append(result)
                    changed = True
                    break
            if changed:
                break
        if changed:
            new_args = new_args_next

    return new_args
