    import subprocess
    import os

    if isinstance(commands, str):
        commands = [commands]

    if args is None:
        args = []
    elif isinstance(args, str):
        args = [args]

    cmd = commands + args

    if env is None:
        env = os.environ

    full_env = dict(env)

    if verbose:
        print "Running command:", " ".join(cmd)

    hide = hide_stderr

    kwargs = dict(cwd=cwd, env=full_env)

    if hide:
        kwargs['stderr'] = subprocess.PIPE

    try:
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, **kwargs)
        out, err = proc.communicate()
        return_code = proc.returncode

        if return_code != 0:
            raise Exception("Command failed with return code {}: {}".format(return_code, " ".join(cmd)))

        if verbose:
            if out:
                print "Command output:", out.decode('utf-8')
        return out
    except Exception as e:
        if verbose:
            print "Error running command:", e
        raise e
