def deep_merge_nodes(nodes):
    if not nodes:
        return []

    # We need to group by key and merge values
    # First, let's collect all keys in order of first appearance
    key_order = []
    key_to_values = {}

    for key, value in nodes:
        key_str = key.value if hasattr(key, 'value') else str(key)

        if key_str not in key_to_values:
            key_to_values[key_str] = {'key': key, 'values': []}
            key_order.append(key_str)

        key_to_values[key_str]['values'].append(value)

    result = []

    for key_str in key_order:
        data = key_to_values[key_str]
        key = data['key']
        values = data['values']

        if len(values) == 1:
            result.append((key, values[0]))
            continue

        # We have multiple values for the same key
        # Check if all values are MappingNode - if so, deep merge them
        # Otherwise, last value wins

        all_mappings = all(
            hasattr(v, 'value') and hasattr(v, 'tag') and 'map' in v.tag 
            for v in values
        )

        if all_mappings:
            # Deep merge all MappingNode values
            merged_value = values[0]

            for v in values[1:]:
                # Merge v into merged_value
                if hasattr(merged_value, 'value') and hasattr(v, 'value') and isinstance(merged_value.value, list) and isinstance(v.value, list):
                    # Deep merge the inner mapping nodes
                    merged_value.value = deep_merge_nodes(
                        [(k, val) for k, val in merged_value.value] + [(k, val) for k, val in v.value]
                    )
                else:
                    # Fallback: last value wins
                    merged_value = v

            result.append((key, merged_value))
        else:
            # Last value wins
            result.append((key, values[-1]))

    return result
