def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    try:
        from ruamel.yaml.nodes import MappingNode, ScalarNode
    except ImportError:
        # Fallback for cases where ruamel.yaml is not available in memory but types are passed,
        # assuming types are compatible with the duck-typing requirements.
        MappingNode = type('MappingNode', (), {})
        ScalarNode = type('ScalarNode', (), {})

    def _is_mapping_node(node):
        return isinstance(node, MappingNode)

    def _is_scalar_node(node):
        return isinstance(node, ScalarNode)

    def _process_mapping(mapping_node):
        merged = {}
        # We need to preserve the key nodes themselves for the output, but we use their string value
        # as the unique identifier for merging.
        # Note: ruamel.yaml MappingNode.value is a list of (key_node, value_node) tuples.

        for key_node, value_node in mapping_node.value:
            key_str = key_node.value
            if key_str in merged:
                existing_value_node = merged[key_str][1]
                if _is_mapping_node(existing_value_node) and _is_mapping_node(value_node):
                    # Deep merge the values
                    new_value_node = _deep_merge_mapping_nodes(existing_value_node, value_node)
                    existing_key_node = merged[key_str][0]
                    merged[key_str] = (existing_key_node, new_value_node)
                else:
                    # Override with last value
                    merged[key_str] = (key_node, value_node)
            else:
                merged[key_str] = (key_node, value_node)

        return list(merged.values())

    def _deep_merge_mapping_nodes(left_node, right_node):
        # left_node and right_node are MappingNode instances
        # Iterate through right_node's entries and merge into a copy of left_node's logic
        # effectively, we just want to produce a new list of tuples.

        # Start with left's items
        left_items = {k.value: (k, v) for k, v in left_node.value}

        for k, v in right_node.value:
            key_str = k.value
            if key_str in left_items:
                existing_k, existing_v = left_items[key_str]
                if _is_mapping_node(existing_v) and _is_mapping_node(v):
                    new_v = _deep_merge_mapping_nodes(existing_v, v)
                    left_items[key_str] = (existing_k, new_v)
                else:
                    # Right wins
                    left_items[key_str] = (k, v)
            else:
                left_items[key_str] = (k, v)

        return list(left_items.values())

    # Top-level merge
    # The input `nodes` is a list of tuples (key_node, value_node).
    # We treat this as the top-level mapping.
    try:
        if not isinstance(nodes, (list, tuple)):
            return nodes

        return _process_mapping_nodes_list(nodes)
    except Exception:
        # If anything fails during structural manipulation, return original to prevent crash
        return nodes

