def _process_mapping_nodes_list(nodes):
    merged = {}
    for key_node, value_node in nodes:
        # A key in a borgmatic config node list at this level is expected to be a ScalarNode
        # representing the name of the key.
        if not _is_scalar_node(key_node):
            # If we don't have a scalar key, we can't safely merge by name. 
            # We might identity-merge or just append, but the spec implies ScalarNode keys.
            # Fallback: use id or repr? The spec says "ScalarNode as a key".
            # If it's not a scalar, we can't extract a string key for duplicate detection easily 
            # unless we assume identity. However, duplicate keys in YAML mappings are tricky.
            # Given the spec, we assume ScalarNode.
            key_str = str(key_node)
        else:
            key_str = key_node.value

        if key_str in merged:
            existing_key_node, existing_value_node = merged[key_str]
            if _is_mapping_node(existing_value_node) and _is_mapping_node(value_node):
                new_value_node = _deep_merge_mapping_nodes(existing_value_node, value_node)
                merged[key_str] = (existing_key_node, new_value_node)
            else:
                merged[key_str] = (key_node, value_node)
        else:
            merged[key_str] = (key_node, value_node)

    return list(merged.values())

