def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def _is_mapping_node(node):
        try:
            from ruamel.yaml.nodes import MappingNode
            return isinstance(node, MappingNode)
        except:
            # Fallback: check if it has a 'value' attribute that is a list of tuples
            return hasattr(node, 'value') and isinstance(node.value, list)

    def _key_string(key):
        try:
            return key.value
        except:
            return str(key)

    def _deep_merge(mapping1, mapping2):
        """
        mapping1 and mapping2 are ruamel.yaml MappingNode instances.
        Returns a new MappingNode with merged values.
        """
        from ruamel.yaml.nodes import MappingNode, ScalarNode

        # Build a dict of key_string -> (key_node, value_node) for mapping1
        merged_dict = {}
        order = []

        for kv in mapping1.value:
            k, v = kv
            ks = _key_string(k)
            merged_dict[ks] = (k, v)
            order.append(ks)

        # Process mapping2
        for kv in mapping2.value:
            k, v = kv
            ks = _key_string(k)

            if ks in merged_dict:
                # Key exists, need to merge if both values are MappingNodes
                existing_k, existing_v = merged_dict[ks]

                if _is_mapping_node(existing_v) and _is_mapping_node(v):
                    # Deep merge the sub-mappings
                    merged_sub = _deep_merge(existing_v, v)
                    merged_dict[ks] = (existing_k, merged_sub)
                else:
                    # Last value wins
                    merged_dict[ks] = (k, v)
            else:
                # New key
                merged_dict[ks] = (k, v)
                order.append(ks)

        # Rebuild the mapping in original order, with new keys appended
        new_value_list = []
        for ks in order:
            k, v = merged_dict[ks]
            new_value_list.append((k, v))

        from ruamel.yaml.nodes import MappingNode
        return MappingNode(tag=mapping1.tag, value=new_value_list)

    # Build a dict to group by key string
    merged_dict = {}
    order = []

    for key, value in nodes:
        ks = _key_string(key)

        if ks in merged_dict:
            existing_key, existing_value = merged_dict[ks]

            if _is_mapping_node(existing_value) and _is_mapping_node(value):
                # Deep merge
                merged_val = _deep_merge(existing_value, value)
                merged_dict[ks] = (key, merged_val)
            else:
                # Last value wins
                merged_dict[ks] = (key, value)
        else:
            merged_dict[ks] = (key, value)
            order.append(ks)

    # Rebuild the list in original order
    result = []
    for ks in order:
        k, v = merged_dict[ks]
        result.append((k, v))

    return result
