def deep_merge_nodes(nodes):
    if not nodes:
        return []

    # Group nodes by their key value
    key_map = {}
    for key, value in nodes:
        # Use the key's value as the grouping key
        if key.value not in key_map:
            key_map[key.value] = []
        key_map[key.value].append((key, value))

    merged_result = []

    for key_value, key_value_nodes in key_map.items():
        # Get the first key node (they should all have the same value)
        first_key = key_value_nodes[0][0]

        # If there's only one node with this key, just use it
        if len(key_value_nodes) == 1:
            merged_result.append(key_value_nodes[0])
            continue

        # Check if all values are MappingNodes
        all_mapping_nodes = all(isinstance(value, MappingNode) for _, value in key_value_nodes)

        if not all_mapping_nodes:
            # If there are non-MappingNode values, the last one wins
            merged_result.append(key_value_nodes[-1])
        else:
            # All values are MappingNodes, so we need to deep merge them
            # Collect all keys from all MappingNodes
            merged_values = []
            merged_keys = {}

            for _, mapping_node in key_value_nodes:
                for inner_key, inner_value in mapping_node.value:
                    if inner_key.value not in merged_keys:
                        merged_keys[inner_key.value] = []
                    merged_keys[inner_key.value].append((inner_key, inner_value))

            # Now merge the inner nodes
            merged_inner_nodes = []
            for inner_key_value, inner_nodes in merged_keys.items():
                if len(inner_nodes) == 1:
                    merged_inner_nodes.append(inner_nodes[0])
                else:
                    # Check if all inner values are MappingNodes
                    inner_all_mapping = all(isinstance(v, MappingNode) for _, v in inner_nodes)
                    if not inner_all_mapping:
                        # Last one wins
                        merged_inner_nodes.append(inner_nodes[-1])
                    else:
                        # Recursive deep merge for the inner MappingNodes
                        merged_inner_nodes.append(deep_merge_mapping_nodes(inner_nodes))

            # Create a new MappingNode with the merged values
            merged_mapping_node = MappingNode(
                tag='tag:yaml.org,2002:map',
                value=merged_inner_nodes
            )
            merged_result.append((first_key, merged_mapping_node))

    return merged_result

