            # Only update remaining_arguments if this subparser claimed some arguments
            # The new remaining arguments are what's left after this subparser tried
            remaining_arguments = unparsed
        except SystemExit:
            # If the subparser exits (e.g. due to error or help), ignore it for this round
            # but keep going to other subparsers
            continue

    return (parsed_namespaces, remaining_arguments)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not size or not isinstance(size, str):
        return 0

    size = size.strip()
    if not size:
        return 0

    # Define suffix multipliers (decimal, base 1000)
    multipliers = {
        'B': 1,
        'K': 1000,
        'M': 1000*1000,
        'G': 1000*1000*1000,
        'T': 1000*1000*1000*1000,
        'P': 1000*1000*1000*1000*1000,
    }

    # Check if the last character is a suffix
    last_char = size[-1].upper()
    if last_char in multipliers:
        try:
            value = float(size[:-1].strip())
        except ValueError:
            return 0
        return int(value * multipliers[last_char])
    else:
        # No suffix, assume bytes
        try:
            return int(float(size.strip()))
        except ValueError:
            return 0

