def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    if number == 0:
        result = alphabet[0]
    else:
        result = ""
        while number > 0:
            number, digit = divmod(number, len(alphabet))
            result = alphabet[digit] + result

    if padding is not None:
        if padding < len(result):
            raise ValueError("Padding cannot be less than the length of the result")
        result = result.zfill(padding)

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        base = len(alphabet)
        negative = number < 0
        number = abs(number)
        while number > 0:
            digits.append(alphabet[number % base])
            number //= base
        if negative:
            digits.append('-')
        result = ''.join(reversed(digits))
    if padding is not None and len(result) < padding:
        result = result.rjust(padding, alphabet[0])
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    if number < 0:
        raise ValueError("Number must be non-negative")

    if number == 0:
        result = alphabet[0]
    else:
        result = []
        base = len(alphabet)
        while number > 0:
            number, remainder = divmod(number, base)
            result.append(alphabet[remainder])
        result.reverse()
        result = ''.join(result)

    if padding is not None and len(result) < padding:
        result = result + alphabet[0] * (padding - len(result))

    return result

