def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    if platform == 'this':
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1
    elif platform not in (0, 1):
        raise ValueError("platform must be 'this', 0, or 1")

    if not isinstance(s, str):
        raise TypeError("s must be a string")

    if platform == 1:
        # POSIX-style splitting
        # Use shlex.split for proper POSIX shell-like splitting
        import shlex
        try:
            return shlex.split(s)
        except ValueError:
            # Fallback to simple regex splitting on whitespace
            return [arg for arg in re.split(r'\s+', s) if arg if arg and arg != '']
    else:
        # Windows/CMD style splitting
        # On Windows, command-line parsing is more complex.
        # A simple approximation: split on whitespace, but handle quoted strings.
        # This is a simplified version that may not handle all edge cases.
        result = []
        current = ''
        in_quotes = False
        for char in s:
            if char == '"':
                in_quotes = not in_quotes
                current += char
            elif char.isspace() and not in_quotes:
                if current:
                    result.append(current)
                    current = ''
            else:
                current += char
        if current:
            result.append(current)
        return result
