def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive path {archive_path} does not exist")

    # Determine the destination directory
    if filename:
        dest_dir = os.path.join(str(tmp_path), filename)
    else:
        dest_dir = str(tmp_path)

    # Ensure the destination directory exists
    os.makedirs(dest_dir, exist_ok=True)

    # Determine archive type based on extension
    if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
        subprocess.run(['tar', '-xzf', archive_path, '-C', dest_dir], check=True)
    elif archive_path.endswith('.tar.bz2') or archive_path.endswith('.tbz2'):
        subprocess.run(['tar', '-xjf', archive_path, '-C', dest_dir], check=True)
    elif archive_path.endswith('.tar'):
        subprocess.run(['tar', '-xf', archive_path, '-C', dest_dir], check=True)
    elif archive_path.endswith('.zip'):
        subprocess.run(['unzip', archive_path, '-d', dest_dir], check=True)
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

    # Return the file:// URL to the destination directory
    return f"file://{dest_dir}"

