def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        result = subprocess.run(['git', 'ls-files', '--others', '--ignored', '--exclude-standard'], capture_output=True, text=True, check=True)
        files = result.stdout.strip().splitlines()
        if not files:
            return ""
        ignored_files = [file for file in files if file in ignored]
        if not ignored_files:
            return ""
        sorted_files = sorted(ignored_files)
        return ",".join(sorted_files)
    except subprocess.CalledProcessError as e:
        print("Error running git command:", e.stderr)
        return ""

def parse_frequency(frequency):
    """Determine a datetime.timedelta value from a JSON request.

    Returns None if the frequency is None or 'always'.
    Otherwise, returns a positive datetime.timedelta value.

    Raises ValueError if the frequency cannot be parsed.
    """
    if frequency is None or frequency == 'always':
        return None
    elif isinstance(frequency, int):
        #api.asAPI errors if frequency is int instead of string
        return datetime.timedelta(seconds=frequency)
    try:
        m = re.match(r'(\d+)\s*([a-z]*)', frequency)
    except Exception as e:
        raise ValueError(e)
    if not m or not m.group(2):
        raise ValueError("Invalid frequency.")

    frequency_param = {m.group(2): int(m.group(1))}

    try:
        return datetime.timedelta(**frequency_param)
    except Exception as e:
        raise ValueError(e)

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    match = re.match(r"^(?P<amount>-?\d+)\s*(?P<unit>\w+)$", frequency)
    if not match:
        raise ValueError(f"Invalid frequency string: {frequency!r}")

    amount = int(match.group("amount"))
    unit = match.group("unit").lower()

    if unit == "year" or unit == "years":
        return datetime.timedelta(days=365 * amount)
    elif unit == "month" or unit == "months":
        return datetime.timedelta(days=30 * amount)
    elif unit == "week" or unit == "weeks":
        return datetime.timedelta(weeks=amount)
    elif unit == "day" or unit == "days":
        return datetime.timedelta(days=amount)
    elif unit == "hour" or unit == "hours":
        return datetime.timedelta(hours=amount)
    elif unit == "minute" or unit == "minutes":
        return datetime.timedelta(minutes=amount)
    elif unit == "second" or unit == "seconds":
        return datetime.timedelta(seconds=amount)
    else:
        raise ValueError(f"Unknown time unit: {unit!r}")

