def subprocess_run_helper(func, *args, timeout, extra_env=None):
    """
    Run a function in a sub-process.

    Parameters
    ----------
    func : function
        The function to be run.  It must be in a module that is importable.
    *args : str
        Any additional command line arguments to be passed in
        the first argument to ``subprocess.run``.
    extra_env : dict[str, str]
        Any additional environment variables to be set for the subprocess.
    """
    import multiprocessing
    import sys
    import os

    def _run_function(func, args):
        try:
            # Reconstruct the function call
            if args:
                func(*args)
            else:
                func()
        except Exception as e:
            print(f"Error in subroutine: {e}", file=sys.stderr)
            sys.exit(1)
        else:
            sys.exit(0)

    # Prepare command
    cmd = [sys.executable, "-c", f"from {func.__module__} import {func.__name__} as f; f{repr(args)}"]

    # Prepare environment
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)

    try:
        process = subprocess.Popen(
            cmd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )

        stdout, stderr = process.communicate(timeout=timeout)

        if process.returncode != 0:
            raise RuntimeError(
                f"Subprocess failed with exit code {process.returncode}. "
                f"stderr: {stderr.decode('utf-8', errors='replace')}"
            )

        return stdout.decode('utf-8', errors='replace')

    except subprocess.TimeoutExpired:
        process.kill()
        process.wait()
        raise TimeoutError(f"Subprocess timed out after {timeout} seconds")
    except Exception as e:
        raise RuntimeError(f"Failed to run subprocess: {e}")

def _resolve_string(matcher):
    parts = matcher.split('$')
    if len(parts) < 2:
        raise ValueError("Invalid matcher: expected at least 2 parts after splitting by '$'")

    # The first part is empty or a prefix, ignore it and take the rest
    var_expr = parts[1]
    if len(parts) > 2:
        # If there are more parts, they are appended as a literal suffix
        suffix = '$'.join(parts[2:])
    else:
        suffix = ""

    # Check if var_expr contains a default value (e.g., VAR|default)
    if '|' in var_expr:
        var_name, default_value = var_expr.split('|', 1)
    else:
        var_name = var_expr
        default_value = None

    value = os.environ.get(var_name, default_value)
    if value is None and default_value is None:
        raise EnvironmentError(f"Environment variable '{var_name}' is not defined and no default was provided")

    result = value + suffix
    return result

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if ':-' in matcher:
        name, default_value = matcher.split(':-', 1)
    else:
        name, default_value = matcher, None

    value = os.environ.get(name)

    if value is None:
        if default_value is not None:
            return default_value
        raise EnvironmentError(f"Environment variable '{name}' is not set and no default value was provided.")

    return value

