def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    cmd = commands + args
    process = None

    if verbose:
        print("$ " + " ".join(str(arg) for arg in cmd))

    try:
        process = subprocess.Popen(cmd, cwd=cwd, env=env, 
                                   stdout=subprocess.PIPE, 
                                   stderr=subprocess.PIPE if hide_stderr else None)
        stdout_data, stderr_data = process.communicate()
        if process.returncode != 0:
            error_output = stderr_data.decode('utf-8', errors='replace') if hide_stderr else ""
            raise subprocess.CalledProcessError(process.returncode, cmd, stdout_data, error_output)
        if not hide_stderr and stderr_data and verbose:
            sys.stderr.write(stderr_data.decode('utf-8', errors='replace'))
        return stdout_data.decode('utf-8', errors='replace') if stdout_data else ""
    except subprocess.CalledProcessError as exc:
        error_message = exc.stderr.decode('utf-8', errors='replace') if exc.stderr else ""
        print("Command failed with return code {}: {}".format(exc.returncode, error_message))
        raise
    except FileNotFoundError:
        raise FileNotFoundError("Command not found: {}".format(commands[0]))
    finally:
        if process:
            if process.wait() != 0:
                pass

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s).

    :param commands: A command or a list of commands.
    :param args: Arguments for the command.
    :param cwd: The working directory for the command.
    :param verbose: If True, prints the command before executing it.
    :param hide_stderr: If True, hides stderr output.
    :param env: Environment variables to set for the command.
    """
    if isinstance(commands, str):
        command_full = f"{commands} {' '.join(args)}"
    elif isinstance(commands, list):
        command_full = ' '.join(commands + args)
    else:
        raise ValueError("Invalid type for commands. Must be a string or a list.")

    if verbose:
        print(f"Executing: {command_full}")

    try:
        if hide_stderr:
            stderr = subprocess.DEVNULL
        else:
            stderr = subprocess.PIPE

        with subprocess.Popen(
            commands,
            args,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr,
            env=env
        ) as process:
            stdout, _ = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(
                    process.returncode,
                    command_full,
                    output=stdout,
                    stderr=_
                )
            if not hide_stderr and _ and verbose:
                print(_.decode('utf-8'))
            return stdout
    except subprocess.CalledProcessError as e:
        if not hide_stderr and e.stderr:
            print(e.stderr.decode('utf-8'))
        raise

