def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    for child, p, parent in graph.triples((None, prop, None)):
        if child not in roots:
            roots.add(child)
    for parent in roots:
        for child in graph.subjects(prop, parent):
            roots.discard(child)
    return roots

