def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    if overrides is None:
        overrides = {}

    logger = logging.getLogger(__name__)
    configs = {}
    errors = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                content = f.read()

            if resolve_env:
                # Replace environment variables in the configuration content
                content = os.path.expandvars(content)

            # Attempt to parse as YAML, if that fails try TOML or JSON
            try:
                config_data = yaml.safe_load(content)
                if not isinstance(config_data, dict):
                    raise ValueError("YAML content is not a mapping")
            except yaml.YAMLError:
                try:
                    config_data = toml.loads(content)
                except toml.TomlDecodeError:
                    config_data = json.loads(content)

            # Apply overrides
            for key, value in overrides.items():
                config_data[key] = value

            configs[filename] = config_data

        except (IOError, OSError) as e:
            logger.warning("Failed to open config file %s: %s", filename, e)
            record = logger.makeRecord(
                logger.name, logging.WARNING, __file__, 0, "Failed to open config file %s: %s" % (filename, e), (e,), None
            )
            errors.append(record)
        except (yaml.YAMLError, toml.TomlDecodeError, json.JSONDecodeError, ValueError) as e:
            logger.warning("Failed to parse config file %s: %s", filename, e)
            record = logger.makeRecord(
                logger.name, logging.WARNING, __file__, 0, "Failed to parse config file %s: %s" % (filename, e), (e,), None
            )
            errors.append(record)
        except Exception as e:
            logger.warning("Unexpected error processing config file %s: %s", filename, e)
            record = logger.makeRecord(
                logger.name, logging.WARNING, __file__, 0, "Unexpected error processing config file %s: %s" % (filename, e), (e,), None
            )
            errors.append(record)

    return configs, errors

