    for bin_ in hist.bins:
        content = bin_.content
        if get_coordinate == "left":
            x = bin_.left
        elif get_coordinate == "right":
            x = bin_.right
        else:  # middle
            x = (bin_.left + bin_.right) / 2.0
        value = make_value(content)
        if isinstance(value, tuple) or isinstance(value, list):
            if len(value) + 1 != len(field_names):
                raise ValueError("The length of the return value from make_value "
                                 "does not match the number of field_names")
            y_values = value
        else:
            if len(field_names) != 2:
                raise ValueError("The return value from make_value must be a tuple "
                                 "of length matching the number of field_names minus 1")
            y_values = [value]
        point_data = [x] + y_values
        points.append(point_data)
    graph = Graph(field_names=field_names, data=points, scale=graph_scale)
    return graph

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not hasattr(iface, '__class__'):
        raise TypeError('iface must be a class')
    if not hasattr(candidate, '__class__'):
        raise TypeError('candidate must be a class')
    if tentative:
        # In tentative mode, just check if the interface method exists
        for name in dir(iface):
            if name.startswith('__') and name.endswith('__'):
                continue
            if not hasattr(candidate, name):
                return False
    else:
        # Strict mode: check method signatures
        for name in dir(iface):
            if name.startswith('__') and name.endswith('__'):
                continue
            iface_method = getattr(iface, name)
            cand_method = getattr(candidate, name, None)
            if cand_method is None:
                return False
            # Basic check: if it's callable in iface, it should be in candidate
            if callable(iface_method) and not callable(cand_method):
                return False
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if candidate is iface:
        return True
    if not isinstance(candidate, type):
        raise TypeError('candidate must be a class')
    if not isinstance(iface, (list, tuple)):
        iface = [iface]
    for i in iface:
        if not isinstance(i, str):
            raise TypeError('iface must be a string or a list of strings')
        if not hasattr(candidate, i):
            if tentative:
                continue
            raise AttributeError('candidate %s does not have attribute %s' % (candidate, i))

