def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        result = explicit_mc
    else:
        result = type
        for base in bases:
            if type(base) is not type:
                raise TypeError("metaclasses must inherit from type")
            if base.__class__ is not type:
                base_mc = base.__class__
                if isinstance(result, base_mc):
                    # The new metaclass is a candidate, and the current one passes.
                    pass
                elif isinstance(base_mc, result):
                    # The base's metaclass is a subclass of the current candidate, so use it.
                    result = base_mc
                else:
                    raise TypeError("metaclass conflict: the metaclass of a derived"
                                    " class must be a (non-strict) subclass"
                                    " of the metaclasses of all its bases")
    return result

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise ValueError("bases must be a non-empty list of classes")

    meta = explicit_mc
    for base in bases:
        if not isinstance(base, type):
            raise TypeError("All bases must be classes, got %r" % type(base))
        base_meta = type(base)
        if meta is None:
            meta = base_meta
        else:
            # The metaclass must be a subclass of all base metaclasses
            if not (isinstance(meta, base_meta) or issubclass(meta, base_meta)):
                raise TypeError("metaclass %r not a subclass of %r" % (meta, base_meta))
            if not isinstance(base_meta, meta) and not issubclass(base_meta, meta):
                # If base_meta is not a subclass of meta, meta must be updated to base_meta
                # Actually, the rule is: the final metaclass must be a subclass of all base metaclasses.
                # If current meta is not a subclass of base_meta, we need to pick the one that is a subclass of both.
                # In Python, it's the most derived of the metaclasses.
                if issubclass(base_meta, meta):
                    continue
                elif issubclass(meta, base_meta):
                    meta = base_meta
                else:
                    raise TypeError("conflicting metaclasses: %r and %r" % (meta, base_meta))

    if meta is None:
        meta = type

    return meta

def determineMetaclass(bases, explicit_mc=None):
    metas = []
    # add bases
    for b in bases:
        mb = getattr(b, '__metaclass__', None)
        if mb is None and isinstance(b, type):
            mb = type(b)
        if mb is None:
            raise TypeError('Unable to find metaclass for %s' % b)
        metas.append(mb)
    # common base of found metaclasses
    # - find common base of all metaclasses
    common = metas[0]
    for m in metas[1:]:
        common = determineMetaclass([common, m])
    # if there is an explicit __metaclass__ -> make sure it is a subtype
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError('explicit __metaclass__ must be a type')
        if not issubclass(explicit_mc, common):
            raise TypeError('explicit __metaclass__ must be a subtype of %s' % common)
        common = explicit_mc
    return common

def determineMetaclass(bases, explicit_mc=None):
    metaclass = None
    if explicit_mc is not None:
        metaclass = explicit_mc
    elif bases:
        for base in bases:
            base_meta = getattr(base, '__class__', None)
            if base_meta is not None and base_meta is not type:
                if metaclass is None:
                    metaclass = base_meta
                elif metaclass is not base_meta:
                    raise TypeError("metaclass conflict")
        if metaclass is None:
            metaclass = type
    else:
        metaclass = type
    return metaclass

