def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    document, code, exception = fetch_document(
        url=url,
        path="/.well-known/nodeinfo",
    )
    if exception:
        return None
    nodeinfo = parse_nodeinfo(document)
    if not nodeinfo:
        return None
    version = nodeinfo.get("version")
    if not version:
        return None
    server = nodeinfo.get("server")
    if not server:
        return None
    if document_path is None:
        document_path = nodeinfo.get("links", [{}])[0].get("href", "/nodeinfo/1.0")
    document, code, exception = fetch_document(url=url, path=document_path)
    if exception:
        return None
    return parse_nodeinfo(document)

