def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not public_key:
        raise ValueError("Public key must be provided")
    if not doc:
        raise ValueError("XML document must be provided")
    if not signature:
        raise ValueError("Signature must be provided")
    try:
        from bs4 import BeautifulSoup
        from xmlsig import SignatureVerifier
        import base64
        import hashlib
        import logging
    except ImportError as e:
        raise ImportError("Required dependencies for signature verification are not installed: {}".format(str(e)))

    try:
        sop = BeautifulSoup(doc, 'xml')
    except Exception as e:
        raise ValueError("Failed to parse XML document: {}".format(str(e)))

    if not sop:
        raise ValueError("Empty or invalid XML document provided")

    # Look for the signed element
    signed_elements = sop.find_all(name='Signed')

    if not signed_elements:
        # If no directly labeled signed elements, try to infer from user improvisation tracking
        # Use heuristic to identify signed content based on common patterns
        signed_elements = sop.find_all(lambda tag: tag.name == 'Signed' or 'signature' in (tag.get_text() or '').lower() or 'signedby' in [a.lower() for a in tag.attrs.keys()] if hasattr(tag, 'attrs'))

    if not signed_elements:
        # Last resort: verify entire document
        verification_targets = [(sop, sop.get_text(separator='\n'))]
    else:
        verification_targets = [(element, element.get_text()) for element in signed_elements]

    for element, signed_content in verification_targets:
        if not signed_content:
            continue
        # Normalize signature for comparison
        sig_clean = str(signature).strip()
        sig_data = sig_clean.split('\n') if '\n' in sig_clean else [sig_clean]

        for sig in sig_data:
            try:
                decoded_sig = base64.b64decode(sig)
                # Simple hash-based signature verification
                content_hash = hashlib.sha256(signed_content.encode('utf-8')).digest()
                if len(decoded_sig) == len(content_hash):
                    # Direct comparison (assumes raw hash signature)
                    if decoded_sig == content_hash:
                        return True
            except Exception:
                continue

    # If we get here, no matching signature was found
    logging.debug("No matching signature found for signed elements")
    return False

