def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        from cryptography.hazmat.primitives.asymmetric import ec
        from cryptography.hazmat.primitives import serialization
        from cryptography.exceptions import InvalidSignature

        if not public_key:
            raise ValueError("Public key is required")

        # If the public key is a string, try to decode it as DER
        if isinstance(public_key, str):
            import base64
            try:
                key_bytes = base64.b64decode(public_key)
            except Exception:
                key_bytes = public_key.encode('utf-8')
            try:
                public_key = ec.EllipticCurvePublicKey.from_encoded_point(
                    ec.SECP256R1(), key_bytes)
            except Exception:
                try:
                    public_key = serialization.load_der_public_key(key_bytes)
                except Exception:
                    raise ValueError("Invalid public key format")
        elif isinstance(public_key, bytes):
            try:
                public_key = ec.EllipticCurvePublicKey.from_encoded_point(
                    ec.SECP256R1(), public_key)
            except Exception:
                public_key = serialization.load_der_public_key(public_key)

        # If signature is a string, decode from base64
        if isinstance(signature, str):
            import base64
            try:
                signature = base64.b64decode(signature)
            except Exception:
                signature = signature.encode('utf-8')

        # Verify the signature
        public_key.verify(
            signature,
            doc,
            ec.ECDSA(__import__('cryptography.hazmat.primitives.hashes', fromlist=['SHA256']).SHA256())
        )
        return True

    except InvalidSignature:
        return False
    except Exception:
        return False
