            rel = link.get("rel")
            href = link.get("href")
            if rel == "lrdd":
                link_dict.setdefault("lrdd", href)
        else:
            rel = link.get("rel")
            href = link.get("href", "")
            if rel == "lrdd":
                link_dict.setdefault("lrdd", href)

    hcard_url = None
    for link in links:
        if isinstance(link, dict):
            link_type = link.get("type")
            rel = link.get("rel")
            href = link.get("href")
            if link_type == "text/html" and rel == "http://microformats.org/profile/hcard":
