def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    stripped_document = document.strip()
    if stripped_document.startswith("{"):
        try:
            parsed = json.loads(stripped_document)
        except (ValueError, TypeError):
            return None
        if not isinstance(parsed, dict):
            return None
        if "subject" in parsed and "links" in parsed:
            return parsed
        return None
    else:
        parser = etree.XMLParser()
        try:
            tree = etree.fromstring(stripped_document.encode("utf-8"), parser)
        except Exception:
            return None
        result = {"subject": tree.get("resource", ""), "links": []}
        for link in tree.findall(".//{http://docs.oasis-open.org/wsr/2004/08/xrd}Link"):
            result["links"].append({
                "rel": link.get("rel"),
                "href": link.get("href"),
                "type": link.get("type"),
            })
        return result

