def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # First, try to parse as JSON (new format)
    try:
        data = json.loads(document)
        # Check if it's a valid webfinger JSON response
        if isinstance(data, dict) and "links" in data:
            return data
    except (json.JSONDecodeError, ValueError):
        # If JSON parsing fails, try to parse as XRD (old format)
        pass

    # Parse as XRD (old format)
    try:
        root = etree.fromstring(document)
        # Find the namespace URI
        ns_uri = root.tag.split('}')[0][1:] if '}' in root.tag else ''
        ns = {'xrd': ns_uri} if ns_uri else {}

        # Extract subject
        subject_elem = root.find('xrd:Subject', ns)
        resource = subject_elem.text if subject_elem is not None else None

        # Extract links
        links = []
        for link_elem in root.findall('xrd:Link', ns):
            href = link_elem.get('href')
            rel = link_elem.get('rel', '')
            templated = link_elem.get('templated', 'false') == 'true'

            link_data = {
                "href": href,
                "templated": templated
            }

            if rel:
                link_data["rel"] = rel

            links.append(link_data)

        if resource is not None or links:
            return {
                "subject": resource,
                "links": links
            }
    except Exception as e:
        pass

    # If both parsing attempts fail, return an empty dict or raise
    return {}
