def try_retrieve_webfinger_document(handle):
    try:
        index = handle.index("@")
    except ValueError:
        return None
    if index <= 2:
        return None
    domain = handle[index + 1:]
    url = "https://{} /.well-known/webfinger?resource=acct:{}".format(domain, quote(handle))
    try:
        response = requests.get(url, timeout=10)
    except requests.RequestException:
        return None
    if response.status_code != 200:
        return None
    return response.text

