def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
            condition
    """
    if not isinstance(options_spec, (list, tuple)):
        options_spec = options_spec or []

    required_args = []
    for spec in options_spec:
        if not isinstance(spec, dict):
            continue

        required_when = spec.get('required_when')
        if not required_when:
            continue

        arg_name = spec.get('arg') or spec.get('name')
        if not arg_name:
            continue

        # Check if the condition is met
        # The exact condition logic may vary, but typically it checks if 
        # a certain argument is present or has a certain value.
        # Assuming a simple structure where required_when is a string 
        # representing another argument name, or a tuple (arg_name, value).
        # Based on common patterns in such system tests:
        # If required_when is a string, check if that arg is in args.
        # If required_when is a tuple, check if args[arg] == value.

        condition_met = False
        if isinstance(required_when, str):
            # required_when is the name of another argument
            if required_when in args:
                condition_met = True
        elif isinstance(required_when, (list, tuple)) and len(required_when) >= 1:
            cond_arg = required_when[0]
            if len(required_when) > 1:
                cond_value = required_when[1]
                if args.get(cond_arg) == cond_value:
                    condition_met = True
            else:
                if cond_arg in args:
                    condition_met = True

    return [arg_name for arg_name in required_args if arg_name]

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditionally_required_args = []
    for option in options_spec:
        if 'required_when' not in option:
            continue
        condition = option['required_when']
        if isinstance(condition, str):
            try:
                condition_matched = eval(condition, dict(args=args))
            except Exception:
                condition_matched = False
        else:
            condition_matched = condition
        if condition_matched:
            conditionally_required_args.append(option['name'])
    return conditionally_required_args

