    if verbose is not None:
        cmd.extend(["-v"] * int(verbose))

    # Add extra vars
    if extra_vars is not None:
        if isinstance(extra_vars, dict):
            for key, value in extra_vars.items():
                cmd.append("--extra-vars")
                cmd.append("{}={}".format(key, value))
        else:
            cmd.append("--extra-vars")
            cmd.append(str(extra_vars))

    # Add direct ansible args
    if ansible_args is not None:
        if isinstance(ansible_args, dict):
            for arg, value in ansible_args.items():
                if arg.startswith("-"):
                    cmd.append(arg)
                else:
                    cmd.append("--{}".format(arg.lstrip("-")))
                if value is not None:
                    cmd.append(str(value))
        else:
            raise TypeError("ansible_args must be a dict")

    # Add playbook path
    cmd.append(str(playbook_path))

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        ir_plugin.log_error("Ansible command failed: {}".format(cmd))
        if e.stdout:
            ir_plugin.log_error("stdout: {}".format(e.stdout))
        if e.stderr:
            ir_plugin.log_error("stderr: {}".format(e.stderr))
        raise
    except OSError as e:
        ir_plugin.log_error("Failed to execute ansible-playbook: {}".format(e))
        raise

def ansible_playbook(ir_workspace, ir_plugin, playbook_path,
                      verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    if ansible_args is None:
        ansible_args = {}

    # Build the command
    cmd = ["ansible-playbook"]

    # Add verbosity if specified
    if verbose is not None:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError("verbose must be a non-negative integer")
        cmd.append("-v" * verbose)

    # Add extra vars
    if extra_vars is None:
        extra_vars = {}
    if not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dictionary")

    if extra_vars:
        # Serialize the extra vars to a JSON string
        extra_vars_json = json.dumps(extra_vars)
        cmd.extend(["--extra-vars", extra_vars_json])

    # Add any additional ansible arguments
    for arg, value in ansible_args.items():
        # Handle boolean values and list/tuple values
        if isinstance(value, bool):
            if value:
                cmd.append(str(arg))
        elif isinstance(value, (list, tuple)):
            cmd.append(arg)
            cmd.extend(str(v) for v in value)
        else:
            cmd.extend([str(arg), str(value)])

    # Add the playbook path
    cmd.append(playbook_path)

    # Execute the command
    return ir_plugin.run_subprocess(ir_workspace, cmd)

